-- FocusVPN Phase 2 · M4: node agent — registration tokens, CA cert storage,
-- desired-state versioning (ADR-004, plans/M4).

-- node_tokens: one-time tokens that allow an agent to register and obtain its
-- mTLS certificate. Consumed on use (used_at set). Generated by admin/seed.
CREATE TABLE node_tokens (
    id          uuid PRIMARY KEY,
    node_id     uuid NOT NULL REFERENCES vpn_nodes (id) ON DELETE CASCADE,
    token_hash  text NOT NULL UNIQUE,       -- SHA-256 of the raw token (hex)
    used_at     timestamptz,
    expires_at  timestamptz NOT NULL,
    created_at  timestamptz NOT NULL DEFAULT now()
);
CREATE INDEX idx_node_tokens_node ON node_tokens (node_id);

-- node_certificates: issued mTLS certificates per agent (for revocation / renewal).
CREATE TABLE node_certificates (
    id           uuid PRIMARY KEY,
    node_id      uuid NOT NULL REFERENCES vpn_nodes (id) ON DELETE CASCADE,
    serial       bigint NOT NULL UNIQUE,
    cert_pem     text NOT NULL,
    issued_at    timestamptz NOT NULL DEFAULT now(),
    expires_at   timestamptz NOT NULL,
    revoked_at   timestamptz
);
CREATE INDEX idx_node_certs_node ON node_certificates (node_id);

-- node_state_versions: monotonically increasing version per node.
-- Incremented whenever the desired peer set for a node changes.
-- Agents poll with ?since=N and receive 304/empty if no change.
CREATE TABLE node_state_versions (
    node_id     uuid PRIMARY KEY REFERENCES vpn_nodes (id) ON DELETE CASCADE,
    version     bigint NOT NULL DEFAULT 0,
    updated_at  timestamptz NOT NULL DEFAULT now()
);

-- Seed an initial version row for every existing node.
INSERT INTO node_state_versions (node_id, version)
SELECT id, 0 FROM vpn_nodes
ON CONFLICT (node_id) DO NOTHING;
